// Libre — Search route (§17, §8.2).
// GET /api/search?q=...        — search episodes
// GET /api/v1/search?q=...     — same (§v1 alias)
//
// §17: D1/SQLite FTS5 in MVP; fallback to indexed LIKE.
// FTS5 availability in D1 is RECOMMENDED — UNTESTED; the LIKE fallback ensures correctness
// even if FTS5 is unavailable.

import type { Env } from "../env";
import { json, badRequest, rateLimited } from "../util/http";

// -- FTS5 MATCH ---------------------------------------------------------------

async function ftsSearch(db: Env["DB"], q: string): Promise<Array<{ media_id: string; type: "series" | "episode"; title: string; overview: string | null }>> {
  // FTS5 query: wrap each term in double-quotes to avoid special characters breaking MATCH.
  const ftsQuery = q
    .split(/\s+/)
    .filter(Boolean)
    .map(t => `"${t.replace(/"/g, '""')}"`)
    .join(" ");
  if (!ftsQuery) return [];

  try {
    const rows = await db.prepare(
      `SELECT e.id, e.title, e.overview
       FROM episode_fts f
       JOIN episodes e ON e.id = f.episode_id
       WHERE episode_fts MATCH ?1
       ORDER BY rank
       LIMIT 25`
    ).bind(ftsQuery).all<{ id: string; title: string; overview: string | null }>();

    return (rows.results ?? []).map(r => ({
      media_id: r.id,
      type: "episode" as const,
      title: r.title,
      overview: r.overview,
    }));
  } catch {
    return []; // §8.2/§17: FTS5 may fail on D1 — delegate to LIKE fallback
  }
}

// -- LIKE fallback -------------------------------------------------------------

async function likeSearch(db: Env["DB"], q: string): Promise<Array<{ media_id: string; type: "series" | "episode"; title: string; overview: string | null }>> {
  const pattern = `%${q}%`;
  const rows = await db.prepare(
    `SELECT e.id, e.title, e.overview
     FROM episodes e
     WHERE e.title LIKE ?1 OR e.overview LIKE ?1
     ORDER BY e.title
     LIMIT 25`
  ).bind(pattern).all<{ id: string; title: string; overview: string | null }>();

  return (rows.results ?? []).map(r => ({
    media_id: r.id,
    type: "episode" as const,
    title: r.title,
    overview: r.overview,
  }));
}

// -- handler -------------------------------------------------------------------

export async function handleSearch(req: Request, env: Env): Promise<Response> {
  const url = new URL(req.url);
  const q = (url.searchParams.get("q") ?? "").trim();
  if (!q) return badRequest("query parameter q is required");

  // §18: apply API_LIMITER
  const limiter = env.API_LIMITER;
  if (limiter) {
    const { success } = await limiter.limit({ key: `search:${url.hostname}` });
    if (!success) return rateLimited();
  }

  // §17: try FTS5 first, fallback to LIKE — always yields correct results
  let results = await ftsSearch(env.DB, q);
  if (!results.length) results = await likeSearch(env.DB, q);

  return json({ query: q, results });
}